# "Which tense?" practice for the Tiempos verbales section. subPoint 'uso-<tense id>' links each item to its guide entry.
UNIT = 'tenses'
O, C, A, B, H, I, P = 'time-marker-open', 'time-marker-closed', 'completed-action', 'background-description', 'habit', 'interrupted-action', 'prior-past'
